package io.github.leetcode.strings;

import java.util.List;

public class CountItemsMatchingARule {
    public int countMatches(List<List<String>> items, String ruleKey, String ruleValue) {
        int index = 0;
        if (ruleKey.equalsIgnoreCase("type")) {
            index = 0;
        } else if (ruleKey.equalsIgnoreCase("color")) {
            index = 1;
        } else if (ruleKey.equalsIgnoreCase("name")) {
            index = 2;
        }

        int count = 0;

        for (List<String> list : items) {
            if (list.get(index).equals(ruleValue)) {
                count++;
            }
        }

        return count;
    }
}

class Solution(object):
    def countMatches(self, items, ruleKey, ruleValue):
        """
        :type items: List[List[str]]
        :type ruleKey: str
        :type ruleValue: str
        :rtype: int
        """
        ans = 0
        for t in items:
            if ruleKey == "type" and t[0] == ruleValue:
                ans += 1
            elif ruleKey == "color" and t[1] == ruleValue:
                ans += 1
            elif ruleKey == "name" and t[2] == ruleValue:
                ans += 1
        return ans
